import{_ as a,o as t,c as s,a2 as o}from"./chunks/framework.BM5YPQmL.js";const u=JSON.parse('{"title":"Recovery","description":"","frontmatter":{},"headers":[],"relativePath":"manual/recovery.md","filePath":"manual/recovery.md"}'),r={name:"manual/recovery.md"};function i(n,e,l,c,h,d){return t(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="recovery" tabindex="-1">Recovery <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Recovery&quot;">​</a></h1><h2 id="crash-artifacts" tabindex="-1">Crash artifacts <a class="header-anchor" href="#crash-artifacts" aria-label="Permalink to &quot;Crash artifacts&quot;">​</a></h2><p>When the kernel catches a fault it writes a crash record before the report path:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; sysdiag               -&gt; crash records (crashlog + dumpinfo)</span></span>
<span class="line"><span>ush&gt; crashlog              (the recorded exceptions of this boot)</span></span>
<span class="line"><span>ush&gt; dumpinfo              (core-dump status)</span></span>
<span class="line"><span>ush&gt; dmesg                 (the kernel log around the event)</span></span></code></pre></div><p><code>crashtest panic|exc|...</code> (classic/direct only - deliberately not a wizard button) injects controlled faults to exercise the machinery.</p><h2 id="the-a-b-escape-hatch" tabindex="-1">The A/B escape hatch <a class="header-anchor" href="#the-a-b-escape-hatch" aria-label="Permalink to &quot;The A/B escape hatch&quot;">​</a></h2><p>A bad slot never bricks the machine:</p><ol><li>Reboot; the GRUB menu offers force-slot-A / force-slot-B.</li><li>Boot the other slot, then from inside it:</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; update rollback</span></span></code></pre></div><h2 id="the-winre-style-recovery-flow" tabindex="-1">The WinRE-style recovery flow <a class="header-anchor" href="#the-winre-style-recovery-flow" aria-label="Permalink to &quot;The WinRE-style recovery flow&quot;">​</a></h2><ol><li>Boot any Open Cube OS ISO (the rescue kit is the installer).</li><li>Attach the broken disk (<code>-drive if=ide,file=broken.img</code>).</li><li>Survey without writing:</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; disk-tool               lsblk / parted / fsck - all read-only here</span></span>
<span class="line"><span>ush&gt; files                   browse the damaged volume once mounted</span></span></code></pre></div><ol start="4"><li>Recover data with <code>files</code> (cp to a mounted FAT32 volume).</li><li>Reinstall if needed: <code>install &lt;dev&gt;</code> (single-system) or the <code>disk-tool</code> A/B manager (update-disk shape).</li></ol><h2 id="the-crash-dump-subsystem" tabindex="-1">The crash dump subsystem <a class="header-anchor" href="#the-crash-dump-subsystem" aria-label="Permalink to &quot;The crash dump subsystem&quot;">​</a></h2><p>Kernel core dumps land under the crash service&#39;s artifacts area with register + stack state; <code>dumpinfo</code> reports where. The <a href="./../internals/crash-dump.html">../internals/crash-dump.md</a> page has the format and the retention policy.</p><h2 id="watchdog" tabindex="-1">Watchdog <a class="header-anchor" href="#watchdog" aria-label="Permalink to &quot;Watchdog&quot;">​</a></h2><p>The watchdog service guards liveness; a hung kernel trips a reset and the next boot&#39;s crashlog shows the watchdog event with the stall context. <code>watchdog</code> (classic / <code>sysdiag</code> table) reports status; the internals are in <a href="./../internals/watchdog.html">../internals/watchdog.md</a>.</p>`,17)])])}const m=a(r,[["render",i]]);export{u as __pageData,m as default};
